import collections

def solve_all_possible_moves(S):
    # A state is a sorted tuple of box sizes.
    # The total sum of boxes is always S.
    initial_state = tuple(sorted([1] * S))

    # We want to find the minimum number of boxes.
    # This is a shortest path problem (BFS) on the state space.
    # However, the state space can be very large.
    # Let's see if we can find the minimum number of boxes for small S.

    queue = collections.deque([(initial_state, 1)])
    visited = {initial_state}

    min_boxes = S

    while queue:
        boxes, num_boxes = queue.popleft()
        if num_boxes < min_boxes:
            min_boxes = num_boxes

        # Try all pairs of boxes
        for i in range(len(boxes)):
            for j in range(i + 1, len(boxes)):
                x = boxes[i]
                y = boxes[j]
                for k in range(1, min(x, y) + 1):
                    # The move: {x, y} -> {x-k, y-k, 2k}
                    temp_boxes = []
                    for idx in range(len(boxes)):
                        if idx != i and idx != j:
                            temp_boxes.append(boxes[idx])

                    if x - k > 0:
                        temp_boxes.append(x - k)
                    if y - k > 0:
                        temp_boxes.append(y - k)
                    temp_boxes.append(2 * k)

                    new_state = tuple(sorted(temp_boxes))
                    if new_state not in visited:
                        visited.add(new_state)
                        queue.append((new_state, len(new_state)))

    return min_boxes

